parameters.jsCode:
// Find sent mails 4-5 days old with no reply logged in the Replies sheet.
// Reads the Replies sheet via $('Log Reply') only when it has run; otherwise
// treats every sent mail in the window as unanswered and drafts a follow-up.
const now = Date.now();
const DAY = 24 * 60 * 60 * 1000;
let repliedThreads = new Set();
try { repliedThreads = new Set($('Log Reply').all().map(i => i.json['Thread ID'])); } catch (e) { repliedThreads = new Set(); }
const due = [];
for (const item of $input.all()) {
  const sentAt = new Date(item.json['Sent At'] || item.json.sentAt || 0).getTime();
  const ageDays = (now - sentAt) / DAY;
  if (ageDays >= 4 && ageDays <= 5 && !repliedThreads.has(item.json['Thread ID'])) {
    due.push({ json: {
      company: item.json.Company, email: item.json.Email,
      role: item.json.Role, subject: 'Re: ' + (item.json.Subject || ''),
      sentAt: item.json['Sent At']
    } });
  }
}
return due;

